// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address accessControl) public {
        // Admissible domain: any non-zero caller and access control address.
        vm.assume(caller != address(0));
        vm.assume(accessControl != address(0));

        // Drive c through the public entry `initialize` from a fuzzed caller.
        vm.prank(caller);
        bool firstOk;
        try c.initialize(accessControl) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // Regardless of the first outcome, a second initialize attempt must
        // never succeed: the initialization version must be latched so that
        // the `initializer` guard can never be satisfied a second time.
        vm.prank(caller);
        bool secondOk;
        try c.initialize(accessControl) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // General rule: initialize() succeeds at most once for any input.
        // The reference satisfies it for every input; the mutant re-latches
        // nothing, so once firstOk is true the mutant also returns true on
        // the retry, breaking the rule for that input.
        assertTrue(!(firstOk && secondOk), "initialize must be one-shot");
    }
}

