// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address admin) public {
        // A fresh contract (no runtime code yet, e.g. inside its constructor) delegates
        // initialization to c. Rule: initialize succeeds from version 0, and after it
        // records version 1 it STILL succeeds from a code-less context via the
        // construction path. The buggy version records version 2 and rejects it.
        Helper h = new Helper(address(c), admin);
        assertTrue(h.secondOk());
    }
}

contract Helper {
    bool public secondOk;

    constructor(address target, address admin) {
        // First initialization: fresh storage, version 0 -> succeeds on both versions.
        (bool s1,) = target.call(abi.encodeWithSignature("initialize(address)", admin));
        require(s1, "first init failed");
        // Second initialization while address(this).code.length == 0 (still constructing):
        // correct contract accepts it via the construction branch (initialized == 1);
        // the buggy one stores 2 and reverts.
        (bool s2,) = target.call(abi.encodeWithSignature("initialize(address)", admin));
        secondOk = s2;
    }
}
